const D = { energy:.6, scale:1, react:.5, speed:1, density:.5, hue:250, coupling:.5, x:.5, y:.5, style:'chemical', act:'breathe', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const clp=(v,a,b)=>Math.max(a,Math.min(b,v)), W=width, H=height;
if(S.lastBeat==null||K.beat<S.lastBeat)S.lastBeat=K.beat; S.lastBeat=K.beat;   // tolerate t0 reset
const hsh=i=>{const s=Math.sin(i*127.1+(P.seed|0)*311.7)*43758.5453;return s-Math.floor(s);};

// --- coarse grid, size + seed keyed ---
const LS=132;
const GW=clp(Math.round(LS*W/Math.max(W,H)),40,160)|0;
const GH=clp(Math.round(LS*H/Math.max(W,H)),24,92)|0;
const N=GW*GH, key=GW+'x'+GH+'_'+(P.seed|0);
if(!S.X||S.key!==key){
  S.key=key;
  S.X=new Float32Array(N); S.Y=new Float32Array(N);
  S.X2=new Float32Array(N); S.Y2=new Float32Array(N);
  S.amp=new Float32Array(N);   // spatial feed-modulation phase field (smooth) -> desynced oscillation
  const Ab=1.2, Bb=1.9+P.react*2.8;
  // smooth low-freq phase field from seed (value-noise-ish): sum of a few sines with seed offsets
  const p1=hsh(11)*6.283, p2=hsh(12)*6.283, p3=hsh(13)*6.283, k1=hsh(14)*0.5+0.15, k2=hsh(15)*0.5+0.15;
  for(let y=0;y<GH;y++)for(let x=0;x<GW;x++){
    const i=y*GW+x;
    const ph=Math.sin(x*k1+p1)+Math.cos(y*k2+p2)+0.6*Math.sin((x+y)*0.11+p3);
    S.amp[i]=ph*2.1;                                   // per-cell phase for the traveling feed wave
    S.X[i]=Ab+(hsh(i*2+1)-0.5)*0.9;                    // near fixed point + noise -> spots nucleate
    S.Y[i]=Bb/Ab+(hsh(i*2+2)-0.5)*0.9;
  }
  if(S.buf&&S.buf.remove)S.buf.remove();
  S.buf=createGraphics(GW,GH); S.buf.pixelDensity(1);
  S.lo=0; S.hi=2; S.burn=140;                          // burn-in so first visible frame is already patterned
}
let X=S.X,Y=S.Y,X2=S.X2,Y2=S.Y2; const buf=S.buf, amp=S.amp;

// --- reaction params + slow section drift (dramaturgy across minutes) ---
const drift=K.t*0.025 + K.section*0.6;
const Ab=1.2;
let Bb=1.9+P.react*2.8 + 0.20*Math.sin(drift) + 0.12*Math.sin(K.t*0.011);
let amdAmp=0.12;
if(P.act==='target'){ Bb=clp(1.75+0.10*Math.sin(drift*0.7),1.6,2.3); amdAmp=0.07; }   // calm pacemaker rings
else if(P.act==='stripes'){ Bb+=0.7; amdAmp=0.22; }                                     // hotter -> oscillating stripe domains
Bb=clp(Bb,1.6,5.6);
// diffusion: density -> feature scale (fewer big <-> many small); coupling -> Dx wavelength fine-tune
const Dx=1.5+P.coupling*1.4;
let Dy=8+(1-P.density)*10;                                                              // 8..18, ratio 3..7
if(P.act==='stripes') Dy*=0.72;
const dt=0.010;
const feedWave=K.t*0.09;                                                                // continuous feed drift = motion floor

// --- perpetual local excitation: seeds new waves; baseline (K) carries it, audio only ADDS ---
const beat=K.pulse*0.6 + A.bass*0.6;
const nInj = P.act==='target' ? 1 : (1+Math.round(P.density*2));
for(let q=0;q<nInj;q++){
  const ang=K.t*(0.13+q*0.05)+q*2.4, rad=P.act==='target'?0.0:0.10+0.12*Math.sin(K.t*0.04+q);
  const cx=Math.floor((0.5+(P.x-0.5)*0.5+Math.cos(ang)*rad)*GW);
  const cy=Math.floor((0.5+(P.y-0.5)*0.5+Math.sin(ang)*rad)*GH);
  const rr=1+Math.round(P.density*2), inj=0.9+beat*1.2;
  for(let dy=-rr;dy<=rr;dy++)for(let dx=-rr;dx<=rr;dx++){
    if(dx*dx+dy*dy>rr*rr)continue;
    const xx=((cx+dx)%GW+GW)%GW, yy=((cy+dy)%GH+GH)%GH, i=yy*GW+xx;
    Y[i]=Math.min(14,Y[i]+inj);                        // kick the inhibitor -> a fresh wavefront
  }
}

// --- step the Brusselator (explicit Euler, 5-point Laplacian, toroidal wrap) ---
// MOTION FLOOR: >=1 step every frame + traveling feed field => never settles, never re-phases at 8s.
const steps = clp(Math.round((6+P.speed*9)*(0.55+0.6*K.intensity)) + (S.burn||0), 4, 40);
let sX=X,sY=Y,dX=X2,dY=Y2;
for(let it=0; it<steps; it++){
  for(let y=0;y<GH;y++){
    const ym=(y-1+GH)%GH, yp=(y+1)%GH, r0=ym*GW, r1=y*GW, r2=yp*GW;
    for(let x=0;x<GW;x++){
      const xm=(x-1+GW)%GW, xp=(x+1)%GW, i=r1+x;
      const xv=sX[i], yv=sY[i];
      const lapX=sX[r1+xm]+sX[r1+xp]+sX[r0+x]+sX[r2+x]-4*xv;
      const lapY=sY[r1+xm]+sY[r1+xp]+sY[r0+x]+sY[r2+x]-4*yv;
      const Al=Ab*(1+amdAmp*Math.sin(amp[i]+feedWave));   // spatially varying feed => desynced breathing waves
      const xy=xv*xv*yv;
      let nx=xv+dt*(Al + xy - (Bb+1)*xv + Dx*lapX);
      let ny=yv+dt*(Bb*xv - xy + Dy*lapY);
      dX[i]=nx<0?0:nx>8?8:nx; dY[i]=ny<0?0:ny>14?14:ny;   // clamp keeps explicit-Euler bounded
    }
  }
  const tx=sX;sX=dX;dX=tx; const ty=sY;sY=dY;dY=ty;       // ping-pong
}
if(sX!==S.X){ S.X.set(sX); S.Y.set(sY); }
S.burn=0;
const fld=S.X;

// --- auto-normalize (smoothed) so luminance stays mid-band as B drifts ---
let mn=1e9,mx=-1e9;
for(let i=0;i<N;i+=2){ const v=fld[i]; if(v<mn)mn=v; if(v>mx)mx=v; }
S.lo+= (mn-S.lo)*0.06; S.hi+= (mx-S.hi)*0.06;
const span=Math.max(0.35,S.hi-S.lo), inv=1/span, lo=S.lo;
const contrast=0.8+P.energy*1.6;

// --- palette: multi-stop ramps, hue-rotated by P.hue; contour = non-representational iso-lines ---
const st=P.style, hd=(((P.hue-250)%360)+360)%360;
function rgb2hsv(r,g,b){ r/=255;g/=255;b/=255; const mx=Math.max(r,g,b),mn=Math.min(r,g,b),d=mx-mn; let h=0; if(d>1e-6){ if(mx===r)h=((g-b)/d)%6; else if(mx===g)h=(b-r)/d+2; else h=(r-g)/d+4; h*=60; if(h<0)h+=360; } return [h, mx<=0?0:d/mx, mx]; }
function hsv2rgb(h,s,v){ const c=v*s, x=c*(1-Math.abs((h/60)%2-1)), m=v-c; let r,g,b; h=((h%360)+360)%360; if(h<60){r=c;g=x;b=0;}else if(h<120){r=x;g=c;b=0;}else if(h<180){r=0;g=c;b=x;}else if(h<240){r=0;g=x;b=c;}else if(h<300){r=x;g=0;b=c;}else{r=c;g=0;b=x;} return [(r+m)*255,(g+m)*255,(b+m)*255]; }
const RAMPS={
  chemical:[[50,30,118],[26,150,158],[240,220,70],[228,66,44]],  // indigo -> teal -> yellow -> red
  thermal:[[6,4,22],[92,20,112],[224,52,40],[255,180,44],[255,250,214]],
  bio:[[8,26,20],[16,120,88],[42,190,120],[186,240,124]],
  litmus:[[40,10,60],[152,30,120],[232,92,162],[246,202,222]]
};
let stops=null;
if(st==='chemical'||st==='thermal'||st==='bio'||st==='litmus'){
  const base=RAMPS[st]; stops=[];
  for(let k=0;k<base.length;k++){ if(hd<1){stops.push(base[k]);} else { const hv=rgb2hsv(base[k][0],base[k][1],base[k][2]); stops.push(hsv2rgb(hv[0]+hd,hv[1],hv[2])); } }
}
const NS=stops?stops.length-1:0;
function ramp(f){ let ff=f*NS; let k=ff|0; if(k>=NS)k=NS-1; const t=ff-k, a=stops[k], b=stops[k+1]; return [a[0]+(b[0]-a[0])*t, a[1]+(b[1]-a[1])*t, a[2]+(b[2]-a[2])*t]; }

buf.loadPixels(); const px=buf.pixels;
for(let y=0;y<GH;y++)for(let x=0;x<GW;x++){
  const i=y*GW+x;
  let f=clp((fld[i]-lo)*inv,0,1);
  f=clp((f-0.5)*contrast+0.5+0.10,0,1);
  let r,g,bl;
  if(st==='contour'){                                 // NON-representational: bright iso-lines on dark ground, hue-driven
    const xm=(x-1+GW)%GW,xp=(x+1)%GW,ym=(y-1+GH)%GH,yp=(y+1)%GH;
    const band=Math.abs(((f*7)%1)-0.5);
    const line=clp((0.12-band)*10,0,1);
    const gx=fld[y*GW+xp]-fld[y*GW+xm], gy=fld[yp*GW+x]-fld[ym*GW+x];
