  } else {
    const c=ramp(f); r=c[0]; g=c[1]; bl=c[2];
  }
  const j=i*4; px[j]=clp(r,0,255); px[j+1]=clp(g,0,255); px[j+2]=clp(bl,0,255); px[j+3]=255;
}
buf.updatePixels();

// --- composite: upscale to full frame; P.scale = display zoom on a centered/pannable sub-rect ---
const zoom=clp(P.scale,1,2.8), sw=GW/zoom, sh=GH/zoom;
