if(st!=='contour' && P.alpha>40){
  push(); blendMode(ADD); noStroke();
  fill((((P.hue%360)+360)%360), st==='litmus'?40:52, 100, clp((5+9*K.swell+A.bass*16)*0.5,0,13));
